// TP : le transistor commande la LED, la broche D8 ne fournit que le courant de base.
const int BASE = 8;

void setup() {
  pinMode(BASE, OUTPUT);
}

void loop() {
  digitalWrite(BASE, HIGH);   // transistor saturé : la LED s'allume
  delay(1000);
  digitalWrite(BASE, LOW);    // transistor bloqué : la LED s'éteint
  delay(1000);
}
